package cn.minidayz.patcher;
import org.json.*;import java.util.*;
/** Reads descriptive data only from an already signature-verified module object. */
public final class FeatureGuide {
 public static JSONArray describe(JSONObject module,JSONObject profile)throws Exception{JSONArray result=new JSONArray(),modules=profile.getJSONArray("modules");JSONObject assistant=module.optJSONObject("assistant");JSONArray guides=assistant==null?null:assistant.optJSONArray("features");for(int i=0;i<modules.length();i++){JSONObject m=modules.getJSONObject(i),description=null;if(guides!=null)for(int k=0;k<Math.min(100,guides.length());k++){JSONObject g=guides.getJSONObject(k);if(m.getString("id").equals(g.optString("module_id")))description=g;}JSONObject item=new JSONObject().put("module_id",m.getString("id")).put("name",m.optString("name")).put("description",description==null?"此插件未提供功能意图说明，仅展示实际操作记录":description.optString("description","未提供说明")).put("required",m.optBoolean("mandatory"));JSONArray operations=m.getJSONArray("operations"),locations=new JSONArray();for(int k=0;k<Math.min(12,operations.length());k++){JSONObject op=operations.getJSONObject(k);locations.put(new JSONObject().put("entry",op.getString("entry")).put("before_sha256",op.getString("before_sha256")).put("after_sha256",op.getString("after_sha256")).put("before_size",op.getLong("before_size")).put("after_size",op.getLong("after_size")));}item.put("locations",locations).put("locations_truncated",operations.length()>12);if(description!=null){item.put("locators",description.optJSONArray("locators")==null?new JSONArray():description.getJSONArray("locators")).put("manual_tests",description.optJSONArray("manual_tests")==null?new JSONArray():description.getJSONArray("manual_tests"));}result.put(item);}return result;}
 public static JSONArray checklist(boolean compatible,boolean key,JSONObject correlation,boolean hasOutput)throws Exception{JSONArray a=new JSONArray();a.put(check("签名模块与输入兼容",compatible?"passed":"blocked","逐项前像、依赖与目标身份校验"));a.put(check("本地签名身份",key?"present":"missing","生成APK时仍需重新验证私钥与证书"));String state=correlation.optString("status");a.put(check("日志与APK关联",state,correlation.optString("message")));a.put(check("输出APK核验",hasOutput?"passed":"not-run","仅在本次构建完成且签名、归档与安装身份校验通过后标记"));a.put(check("游戏运行验证","manual-required","需要实际进入游戏复现问题，不能用打包成功代替"));return a;}
 static JSONObject check(String name,String status,String detail)throws Exception{return new JSONObject().put("name",name).put("status",status).put("detail",detail);}
}
